import { useEffect, useState } from "react";
import { Link, NavLink, Navigate, Route, Routes, useNavigate } from "react-router-dom";
import {
  ArrowRight, BookOpen, CalendarDays, Check, ChevronRight, CircleDollarSign, Coins,
  Gift, Heart, Home, Leaf, Loader2, LockKeyhole, LogOut, Menu, MessageCircle, Music2,
  PenLine, Play, Plus, Search, Send, ShieldCheck, Sparkles, Star, Trash2, UserRound, Wind, X,
} from "lucide-react";
import { api, streamChat } from "./api";
import { fallbackBooks, fallbackJournals, fallbackTherapists, moods } from "./data";

function Logo({ compact = false }) {
  return <Link to="/" className="group flex items-center gap-2.5">
    <span className="relative flex h-9 w-9 items-center justify-center rounded-[13px] bg-ink text-white"><Leaf size={19} strokeWidth={2.4} /><span className="absolute -right-0.5 -top-0.5 h-2 w-2 rounded-full bg-coral" /></span>
    {!compact && <span className="display text-xl font-bold tracking-[-.07em] text-ink">zenheaven</span>}
  </Link>;
}

function Toast({ message, onClose }) {
  if (!message) return null;
  return <div className="fixed bottom-5 left-1/2 z-[60] flex -translate-x-1/2 items-center gap-3 rounded-full bg-ink px-5 py-3 text-sm text-white shadow-soft">
    <Check size={16} className="text-sage" /> {message} <button onClick={onClose} aria-label="Close notification"><X size={15} /></button>
  </div>;
}

function Sidebar({ user, onLogout, mobileVisible = false }) {
  const [open, setOpen] = useState(false);
  const links = [
    { to: "/dashboard", label: "Overview", icon: Home },
    { to: "/chat", label: "Talk to CalmBot", icon: MessageCircle },
    { to: "/journal", label: "My journal", icon: PenLine },
    { to: "/books", label: "Reading room", icon: BookOpen },
    { to: "/music", label: "Sound sanctuary", icon: Music2 },
    { to: "/therapists", label: "Find a therapist", icon: UserRound },
    { to: "/coins", label: "Calm coins", icon: Coins },
  ];
  return <aside className={`fixed inset-y-0 left-0 z-40 flex w-[270px] flex-col border-r border-[#dfe8df] bg-[#fbfcfb] px-5 py-7 transition-transform lg:translate-x-0 ${mobileVisible || open ? "translate-x-0" : "-translate-x-full"}`}>
    <button className="absolute right-4 top-5 lg:hidden" onClick={() => setOpen(false)} aria-label="Close menu"><X size={20} /></button>
    <div className="px-3"><Logo /></div>
    <div className="mt-12 flex-1 space-y-1">
      <p className="eyebrow mb-4 px-3 text-[#8ca095]">Your space</p>
      {links.map(({ to, label, icon: Icon }) => <NavLink key={to} to={to} onClick={() => setOpen(false)} className={({ isActive }) => `group flex items-center gap-3 rounded-2xl px-3 py-3 text-sm font-medium transition ${isActive ? "bg-mint text-ink" : "text-[#708279] hover:bg-[#f0f5f0] hover:text-ink"}`}>
        <Icon size={18} strokeWidth={1.8} /><span>{label}</span>{label === "Talk to CalmBot" && <span className="ml-auto rounded-full bg-coral/15 px-2 py-0.5 text-[10px] font-bold text-coral">AI</span>}
      </NavLink>)}
    </div>
    <div className="rounded-[22px] bg-[#edf4ed] p-4">
      <div className="mb-3 flex items-center gap-2 text-xs font-semibold text-ink"><ShieldCheck size={15} className="text-moss" /> Your space is private</div>
      <p className="text-[11px] leading-relaxed text-[#759083]">Your thoughts belong to you. We keep your journey safe and secure.</p>
    </div>
    <div className="mt-5 flex items-center gap-3 border-t border-[#e4ebe4] pt-5">
      <div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#d5e4d7] text-sm font-bold text-ink">{(user?.full_name || user?.username || "A")[0].toUpperCase()}</div>
      <div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-ink">{user?.full_name || user?.username || "Alex"}</p><p className="text-[11px] text-[#8ca095]">Member since today</p></div>
      <button onClick={onLogout} className="text-[#8ca095] hover:text-coral" title="Log out"><LogOut size={17} /></button>
    </div>
    <button className="fixed inset-0 -z-10 bg-ink/20 lg:hidden" onClick={() => setOpen(false)} aria-label="Close navigation" />
  </aside>;
}

function AppShell({ user, onLogout, children }) {
  const [open, setOpen] = useState(false);
  return <div className="min-h-screen bg-paper grain"><Sidebar user={user} onLogout={onLogout} /><div className="lg:pl-[270px]"><header className="sticky top-0 z-30 flex h-[76px] items-center justify-between border-b border-[#e5ece5]/80 bg-paper/90 px-5 backdrop-blur sm:px-8 lg:hidden"><button onClick={() => setOpen(true)} aria-label="Open menu"><Menu size={22} /></button><Logo compact /><div className="h-8 w-8 rounded-full bg-sage/40" /></header><main>{children}</main></div>{open && <div className="fixed inset-0 z-50 lg:hidden" onClick={() => setOpen(false)}><div onClick={(event) => event.stopPropagation()}><Sidebar user={user} onLogout={onLogout} mobileVisible /></div></div>}</div>;
}

function Landing() {
  return <div className="min-h-screen bg-paper grain">
    <nav className="shell flex h-24 items-center justify-between"><Logo /><div className="hidden items-center gap-8 text-sm font-medium text-[#60766a] md:flex"><a href="#how-it-works">How it works</a><a href="#care">Your care, your way</a><a href="#support">Support</a></div><div className="flex items-center gap-2 sm:gap-3"><Link to="/login" className="rounded-full px-3 py-2 text-sm font-semibold text-ink sm:px-4">Log in</Link><Link to="/register" className="btn-primary px-4 py-2.5 sm:px-5">Get started <ArrowRight size={15} /></Link></div></nav>
    <section className="shell relative overflow-hidden pb-20 pt-12 sm:pt-20 lg:pb-28 lg:pt-24">
      <div className="pointer-events-none absolute -right-20 top-0 h-[440px] w-[440px] rounded-full bg-[#dbeadd] blur-3xl" /><div className="pointer-events-none absolute bottom-0 left-1/3 h-64 w-64 rounded-full bg-[#f1e6dc] blur-3xl" />
      <div className="relative grid items-center gap-14 lg:grid-cols-[1.03fr_.97fr] lg:gap-20">
        <div><p className="eyebrow mb-6 flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-coral" /> A softer way to care for your mind</p><h1 className="display max-w-[680px] text-5xl font-semibold leading-[.98] text-ink sm:text-7xl lg:text-[82px]">Come as you are.<br /><span className="text-moss">Feel more like you.</span></h1><p className="mt-8 max-w-[490px] text-base leading-7 text-[#6e8177] sm:text-lg">A private, human-centered space for the messy middle. Talk it out, write it down, and find small steps toward feeling better.</p><div className="mt-9 flex flex-wrap items-center gap-3"><Link to="/register" className="btn-primary px-6 py-4">Start your journey <ArrowRight size={17} /></Link><Link to="/login" className="flex items-center gap-2 rounded-full px-4 py-3 text-sm font-semibold text-ink">I already have an account <ChevronRight size={16} /></Link></div><div className="mt-9 flex items-center gap-3 text-xs text-[#799083]"><div className="flex -space-x-2"><span className="h-7 w-7 rounded-full border-2 border-paper bg-[#d7b49b]" /><span className="h-7 w-7 rounded-full border-2 border-paper bg-[#a7c2b0]" /><span className="h-7 w-7 rounded-full border-2 border-paper bg-[#ddc4ab]" /></div><span>Joined by 10,000+ people choosing themselves</span></div></div>
        <div className="relative mx-auto w-full max-w-[540px]">
          <div className="relative aspect-[.91] overflow-hidden rounded-[46%_46%_24px_24px] bg-[#c4d8c7]"><div className="absolute inset-0 bg-gradient-to-br from-[#b6d0ba] via-[#dfe8da] to-[#e4d8cd]" /><div className="absolute -left-8 top-12 h-56 w-56 rounded-full bg-[#a7c6ae]/80 blur-2xl" /><div className="absolute bottom-0 right-0 h-[75%] w-[70%] rounded-t-[48%] bg-[#e3c4ad]/80" /><div className="absolute bottom-0 left-[18%] h-[62%] w-[55%] rounded-t-[52%] bg-[#b8866d]/75" /><div className="absolute left-[26%] top-[23%] h-16 w-16 rounded-full bg-[#9d6f60]" /><div className="absolute left-[36%] top-[37%] h-3 w-3 rounded-full bg-ink" /><div className="absolute left-[48%] top-[37%] h-3 w-3 rounded-full bg-ink" /><div className="absolute left-[35%] top-[45%] h-3 w-16 rounded-b-full border-b-2 border-ink/60" /><div className="absolute left-[21%] top-[15%] h-32 w-44 rounded-full bg-ink/80" /><div className="absolute bottom-[17%] left-[13%] h-6 w-52 rotate-[-26deg] rounded-full bg-[#d4b5a0]" /></div>
          <div className="absolute -left-5 bottom-10 rounded-[22px] bg-white/90 p-4 shadow-soft backdrop-blur sm:-left-8"><div className="mb-2 flex items-center gap-2"><span className="flex h-8 w-8 items-center justify-center rounded-xl bg-[#f8ebe6] text-coral"><Heart size={16} fill="currentColor" /></span><span className="text-xs font-semibold">Today’s check-in</span></div><p className="text-sm font-semibold text-ink">You’re doing better<br />than you think.</p></div>
          <div className="absolute -right-2 top-12 rounded-[22px] bg-ink px-4 py-3 text-white shadow-soft sm:-right-9"><p className="text-[10px] uppercase tracking-widest text-sage">Your little win</p><p className="mt-1 text-sm font-semibold">Showed up for yourself <span className="text-[#f4c99b]">✦</span></p></div>
        </div>
      </div>
    </section>
    <section id="care" className="bg-ink py-16 text-white sm:py-24"><div className="shell"><div className="grid gap-10 lg:grid-cols-[.8fr_1.2fr]"><div><p className="eyebrow text-sage">Everything you need, none of the pressure</p><h2 className="display mt-4 max-w-md text-4xl leading-tight sm:text-5xl">Care that meets you where you are.</h2></div><div className="grid gap-3 sm:grid-cols-2"><Feature icon={MessageCircle} title="A space to talk" text="Unpack what’s on your mind with CalmBot, available whenever you are." /><Feature icon={PenLine} title="Room to reflect" text="A private journal that helps you notice patterns and celebrate progress." /><Feature icon={Music2} title="Sounds for your state" text="Mood-based music and books for the moments words don’t quite fit." /><Feature icon={UserRound} title="Human support" text="Find a therapist who feels like the right fit for your story." /></div></div></div></section>
    <footer className="shell flex flex-col justify-between gap-4 py-8 text-xs text-[#829489] sm:flex-row"><Logo /><span>© 2024 ZenHeaven. Made for your softer days.</span></footer>
  </div>;
}

function Feature({ icon: Icon, title, text }) {
  return <div className="rounded-[24px] border border-white/10 bg-white/[.06] p-5"><Icon size={20} className="mb-8 text-sage" /><h3 className="font-semibold">{title}</h3><p className="mt-2 text-sm leading-6 text-[#aebfb1]">{text}</p></div>;
}

function AuthPage({ mode, onAuth }) {
  const navigate = useNavigate(); const [form, setForm] = useState({ username: "", email: "", password: "", full_name: "" }); const [loading, setLoading] = useState(false); const [error, setError] = useState("");
  const isRegister = mode === "register";
  const submit = async (event) => { event.preventDefault(); setLoading(true); setError(""); try { const payload = isRegister ? form : { username: form.username, password: form.password }; const result = await (isRegister ? api.register(payload) : api.login(payload)); localStorage.setItem("zenheaven_token", result.access_token); onAuth(result.user); navigate("/dashboard"); } catch (err) { setError(err.message); } finally { setLoading(false); } };
  return <div className="grid min-h-screen lg:grid-cols-[.9fr_1.1fr]"><div className="hidden bg-ink p-12 text-white lg:flex lg:flex-col lg:justify-between"><Logo /><div className="max-w-md"><div className="mb-7 flex h-14 w-14 items-center justify-center rounded-[20px] bg-sage/20 text-sage"><Leaf size={28} /></div><h1 className="display text-6xl leading-[.98]">A place to<br /><span className="text-sage">come back to.</span></h1><p className="mt-7 max-w-sm leading-7 text-[#a8bbb0]">Your feelings are welcome here. Start wherever feels easiest today.</p></div><p className="text-xs text-[#829d8b]">Private by design · Human when you need it</p></div><div className="flex items-center justify-center p-6 sm:p-12"><div className="w-full max-w-[440px]"><div className="mb-12 flex items-center justify-between lg:hidden"><Logo /><Link to="/" className="text-sm text-[#718279]">Back home</Link></div><p className="eyebrow">{isRegister ? "Your space is ready when you are" : "Welcome back"}</p><h2 className="display mt-4 text-4xl font-semibold">{isRegister ? "Let’s make room for you." : "Good to see you again."}</h2><p className="mt-3 text-sm leading-6 text-[#7e9185]">{isRegister ? "A few details, then you’re in." : "Pick up right where you left off."}</p><form onSubmit={submit} className="mt-9 space-y-4">{isRegister && <div><label className="mb-2 block text-xs font-semibold text-ink">What should we call you?</label><input required className="input" placeholder="Your name" value={form.full_name} onChange={(e) => setForm({ ...form, full_name: e.target.value })} /></div>}<div><label className="mb-2 block text-xs font-semibold text-ink">Username</label><input required className="input" placeholder="e.g. alexsun" value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} /></div>{isRegister && <div><label className="mb-2 block text-xs font-semibold text-ink">Email address</label><input required type="email" className="input" placeholder="you@example.com" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /></div>}<div><div className="mb-2 flex justify-between"><label className="text-xs font-semibold text-ink">Password</label>{!isRegister && <button type="button" className="text-xs font-medium text-moss">Forgot password?</button>}</div><input required minLength={6} type="password" className="input" placeholder="At least 6 characters" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} /></div>{error && <p className="rounded-xl bg-[#fce9e4] px-4 py-3 text-xs leading-5 text-[#a84f3b]">{error}</p>}<button disabled={loading} className="btn-primary mt-3 w-full py-4">{loading ? <Loader2 size={17} className="animate-spin" /> : isRegister ? "Create my space" : "Log me in"} {!loading && <ArrowRight size={16} />}</button></form><div className="my-8 flex items-center gap-3 text-[11px] text-[#9aa9a0]"><span className="h-px flex-1 bg-[#e0e8e0]" /> or <span className="h-px flex-1 bg-[#e0e8e0]" /></div><p className="text-center text-sm text-[#7e9185]">{isRegister ? "Already have a space?" : "New to ZenHeaven?"} <Link className="font-semibold text-moss" to={isRegister ? "/login" : "/register"}>{isRegister ? "Log in" : "Create an account"}</Link></p><p className="mt-8 flex items-center justify-center gap-1.5 text-[11px] text-[#9aa9a0]"><LockKeyhole size={12} /> Your information is private and secure</p></div></div></div>;
}

function PageHeader({ eyebrow, title, description, action }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="eyebrow">{eyebrow}</p><h1 className="display mt-2 text-4xl font-semibold text-ink sm:text-5xl">{title}</h1>{description && <p className="mt-3 max-w-xl text-sm leading-6 text-[#7a8f83]">{description}</p>}</div>{action}</div>;
}

function Dashboard({ user, toast }) {
  const [balance, setBalance] = useState(user?.calm_coins || 100); const [journals, setJournals] = useState(fallbackJournals); const [goals, setGoals] = useState([]); const [streak, setStreak] = useState(4);
  useEffect(() => { Promise.all([api.balance(), api.journals(), api.dailyGoals(), api.streak()]).then(([coin, entries, daily, currentStreak]) => { setBalance(coin.balance ?? 100); setJournals(entries?.length ? entries : fallbackJournals); setGoals(daily || []); setStreak(currentStreak?.current_streak || 0); }).catch(() => {}); }, []);
  const firstName = (user?.full_name || user?.username || "friend").split(" ")[0];
  return <div className="shell py-10 sm:py-14"><PageHeader eyebrow="Saturday, September 5" title={`Good morning, ${firstName}.`} description="A little check-in with yourself can change the shape of a whole day." action={<Link to="/chat" className="btn-primary">How are you feeling? <ArrowRight size={16} /></Link>} /><div className="grid gap-5 xl:grid-cols-[1.4fr_.6fr]"><section className="relative overflow-hidden rounded-[30px] bg-[#dcebdd] p-7 sm:p-9"><div className="relative z-10 max-w-md"><span className="mb-5 inline-flex items-center gap-2 rounded-full bg-white/65 px-3 py-1.5 text-xs font-semibold text-moss"><Sparkles size={14} /> A gentle reminder</span><h2 className="display text-3xl font-semibold leading-tight sm:text-4xl">You don’t have to<br />figure it all out today.</h2><p className="mt-4 max-w-sm text-sm leading-6 text-[#628070]">Just one small, kind thing at a time. What would feel good right now?</p><Link to="/journal" className="mt-7 inline-flex items-center gap-2 text-sm font-bold text-ink">Open your journal <ArrowRight size={16} /></Link></div><div className="absolute -right-8 -top-16 h-64 w-64 rounded-full border-[38px] border-white/30" /><div className="leaf-shape absolute -bottom-10 right-8 h-36 w-24 bg-[#a6c6ae]/70" /></section><section className="panel flex flex-col justify-between p-7"><div className="flex items-start justify-between"><div><p className="eyebrow">Calm coins</p><p className="display mt-3 text-5xl font-semibold">{balance}</p><p className="mt-1 text-xs text-[#829489]">Keep showing up for yourself</p></div><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#fcf0d8] text-[#d99a3c]"><Coins size={22} /></span></div><Link to="/coins" className="mt-8 flex items-center justify-between border-t border-[#e8eee8] pt-4 text-sm font-semibold">See your rewards <ChevronRight size={17} className="text-[#8ba095]" /></Link></section></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section className="panel p-7"><div className="mb-6 flex items-center justify-between"><div><p className="eyebrow">Daily check-in</p><h3 className="display mt-2 text-2xl font-semibold">How are you arriving today?</h3></div><Heart size={21} className="text-coral" /></div><div className="flex gap-2 overflow-x-auto pb-1 scrollbar-none">{moods.map((mood) => <MoodButton key={mood.label} {...mood} onClick={() => toast(`Noted: feeling ${mood.label.toLowerCase()}`)} />)}</div><div className="mt-7 rounded-2xl bg-[#f5f8f5] p-4 text-sm text-[#768b7e]"><span className="font-semibold text-ink">A prompt for you:</span> What’s one thing you’d like to make space for today?</div></section><section className="panel p-7"><div className="flex items-center justify-between"><div><p className="eyebrow">Your rhythm</p><h3 className="display mt-2 text-2xl font-semibold">{streak || 4} day streak</h3></div><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#faeadd] text-coral">✦</div></div><div className="mt-6 flex items-end gap-2">{["M", "T", "W", "T", "F", "S", "S"].map((day, index) => <div key={`${day}-${index}`} className="flex flex-1 flex-col items-center gap-2"><div className={`flex h-9 w-9 items-center justify-center rounded-full text-xs ${index < 5 ? "bg-moss text-white" : index === 5 ? "border-2 border-moss text-moss" : "bg-[#eff4ef] text-[#a9b9ad]"}`}>{index < 5 ? <Check size={14} /> : ""}</div><span className="text-[10px] text-[#91a197]">{day}</span></div>)}</div><p className="mt-5 text-xs leading-5 text-[#829489]">Small steps add up. You’re building something that lasts.</p></section></div><section className="mt-5 panel p-7"><div className="mb-6 flex items-center justify-between"><div><p className="eyebrow">Continue your journey</p><h3 className="display mt-2 text-2xl font-semibold">Your recent reflections</h3></div><Link to="/journal" className="text-sm font-semibold text-moss">View all <ChevronRight size={15} className="inline" /></Link></div><div className="grid gap-3 md:grid-cols-2">{journals.slice(0, 2).map((entry) => <Link to="/journal" key={entry._id} className="group flex items-center gap-4 rounded-2xl border border-[#e4ece4] p-4 transition hover:border-sage"><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#eef4ee] text-lg">✍︎</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{entry.title || "A moment to remember"}</p><p className="mt-1 truncate text-xs text-[#829489]">{entry.content}</p></div><ChevronRight size={16} className="text-[#9aaba0] transition group-hover:translate-x-1" /></Link>)}</div></section></div>;
}

function MoodButton({ label, emoji, color, onClick }) { return <button onClick={onClick} className={`flex min-w-[78px] flex-1 flex-col items-center gap-2 rounded-2xl ${color} px-3 py-4 text-xs font-semibold transition hover:-translate-y-1`}><span className="text-2xl">{emoji}</span>{label}</button>; }

function Chat() {
  const [threads, setThreads] = useState([]); const [activeId, setActiveId] = useState(null); const [messages, setMessages] = useState([]); const [input, setInput] = useState(""); const [thinking, setThinking] = useState(false); const [thought, setThought] = useState(""); const [error, setError] = useState("");
  useEffect(() => { api.threads().then((data) => setThreads(data.threads || [])).catch(() => {}); }, []);
  const selectThread = async (id) => { setActiveId(id); try { const data = await api.thread(id); setMessages((data.messages || []).map((message) => ({ id: message.id, role: message.is_user ? "user" : "assistant", content: message.content }))); } catch { setMessages([]); } };
  const send = async (event) => { event?.preventDefault(); const text = input.trim(); if (!text || thinking) return; setInput(""); setError(""); setMessages((current) => [...current, { id: `local-${Date.now()}`, role: "user", content: text }]); setThinking(true); setThought("Finding the right words for you…"); let response = "";
    try { await streamChat(text, activeId, (eventData) => { if (eventData.type === "thread_id") setActiveId(eventData.data); if (eventData.type === "thinking") setThought(eventData.data); if (eventData.type === "response_start") setMessages((current) => [...current, { id: `assistant-${Date.now()}`, role: "assistant", content: "" }]); if (eventData.type === "token") { response += eventData.data; setMessages((current) => { const copy = [...current]; const last = copy[copy.length - 1]; if (last?.role === "assistant") copy[copy.length - 1] = { ...last, content: response }; return copy; }); } if (eventData.type === "complete") { setThinking(false); api.threads().then((data) => setThreads(data.threads || [])).catch(() => {}); } }); } catch (err) { setError(err.message); setMessages((current) => [...current, { id: `fallback-${Date.now()}`, role: "assistant", content: "I’m here with you. The connection is taking a moment, but you can try sending that again when you’re ready." }]); } finally { setThinking(false); }
  };
  return <div className="shell flex min-h-[calc(100vh-2rem)] flex-col py-8 sm:py-12"><PageHeader eyebrow="A space to be heard" title="Talk it out." description="CalmBot is here to listen without judgment. It’s not a replacement for professional care, but you never have to hold it alone." /><div className="grid min-h-[620px] flex-1 gap-5 lg:grid-cols-[260px_1fr]"><aside className="panel hidden p-4 lg:block"><div className="mb-4 flex items-center justify-between px-2"><p className="eyebrow">Conversations</p><button className="rounded-xl bg-mint p-2 text-moss" onClick={() => { setActiveId(null); setMessages([]); }} aria-label="New conversation"><Plus size={16} /></button></div><button onClick={() => { setActiveId(null); setMessages([]); }} className="mb-2 flex w-full items-center gap-3 rounded-2xl border border-dashed border-[#cbdacb] px-3 py-3 text-left text-sm font-semibold text-moss"><Plus size={17} /> New conversation</button>{threads.map((thread) => <button key={thread.id} onClick={() => selectThread(thread.id)} className={`w-full rounded-2xl px-3 py-3 text-left transition ${activeId === thread.id ? "bg-mint" : "hover:bg-[#f3f7f3]"}`}><p className="truncate text-xs font-semibold">{thread.title}</p><p className="mt-1 truncate text-[10px] text-[#8a9d90]">{thread.last_message || "A new conversation"}</p></button>)}</aside><section className="panel flex min-h-[620px] flex-col overflow-hidden"><div className="flex items-center gap-3 border-b border-[#e5ece5] px-5 py-4 sm:px-7"><span className="flex h-10 w-10 items-center justify-center rounded-2xl bg-[#dcebdd] text-moss"><Sparkles size={19} /></span><div><p className="text-sm font-semibold">CalmBot</p><p className="flex items-center gap-1.5 text-[11px] text-[#829489]"><span className="h-1.5 w-1.5 rounded-full bg-[#7aae82]" /> Here to listen</p></div><div className="ml-auto rounded-full bg-[#f5f8f5] px-3 py-1.5 text-[10px] text-[#829489]"><ShieldCheck size={12} className="mr-1 inline" /> Private conversation</div></div><div className="flex-1 space-y-5 overflow-y-auto p-5 sm:p-8">{messages.length === 0 && <div className="mx-auto max-w-md py-16 text-center"><div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-[24px] bg-mint text-moss"><MessageCircle size={27} /></div><h3 className="display text-2xl font-semibold">What’s on your mind?</h3><p className="mt-3 text-sm leading-6 text-[#829489]">There’s no right way to begin. You could tell me how you’re feeling, what happened today, or just say hello.</p><div className="mt-7 flex flex-wrap justify-center gap-2">{["I feel a little overwhelmed", "Help me wind down", "I need to talk"].map((prompt) => <button key={prompt} onClick={() => setInput(prompt)} className="rounded-full border border-[#dae6da] px-3 py-2 text-xs text-moss hover:bg-mint">{prompt}</button>)}</div></div>}{messages.map((message) => <div key={message.id} className={`flex ${message.role === "user" ? "justify-end" : "justify-start"}`}><div className={`max-w-[84%] rounded-[22px] px-4 py-3 text-sm leading-6 ${message.role === "user" ? "rounded-br-md bg-ink text-white" : "rounded-bl-md bg-[#eff5ef] text-ink"}`}>{message.content || <span className="flex items-center gap-2 text-[#7c9282]"><span className="flex gap-1"><i className="h-1.5 w-1.5 animate-bounce rounded-full bg-moss [animation-delay:-.3s]" /><i className="h-1.5 w-1.5 animate-bounce rounded-full bg-moss [animation-delay:-.15s]" /><i className="h-1.5 w-1.5 animate-bounce rounded-full bg-moss" /></span> Listening…</span>}</div></div>)}{thinking && <p className="text-[11px] text-[#8ba095]"><span className="mr-1 inline-block h-1.5 w-1.5 animate-pulse rounded-full bg-coral" />{thought}</p>}{error && <p className="text-xs text-coral">{error}</p>}</div><form onSubmit={send} className="border-t border-[#e5ece5] p-4 sm:p-5"><div className="flex items-center gap-2 rounded-2xl border border-[#d6e2d6] bg-[#fbfcfb] p-2 focus-within:border-moss"><input className="min-w-0 flex-1 bg-transparent px-3 text-sm outline-none placeholder:text-[#9aaa9f]" value={input} onChange={(e) => setInput(e.target.value)} placeholder="Write what’s on your mind…" /><button disabled={!input.trim() || thinking} className="flex h-10 w-10 items-center justify-center rounded-xl bg-ink text-white transition hover:bg-moss disabled:opacity-40" aria-label="Send message">{thinking ? <Loader2 size={17} className="animate-spin" /> : <Send size={17} />}</button></div><p className="mt-3 text-center text-[10px] text-[#a0afa5]">CalmBot offers support, not medical advice. If you’re in immediate danger, contact local emergency services.</p></form></section></div></div>;
}

function Journal({ toast }) {
  const [entries, setEntries] = useState(fallbackJournals); const [prompts, setPrompts] = useState([]); const [content, setContent] = useState(""); const [mood, setMood] = useState(""); const [saving, setSaving] = useState(false); const [writing, setWriting] = useState(false);
  useEffect(() => { Promise.all([api.journals(), api.prompts()]).then(([data, promptData]) => { if (data?.length) setEntries(data); if (promptData?.length) setPrompts(promptData); }).catch(() => { setPrompts([]); }); }, []);
  const save = async (event) => { event.preventDefault(); if (!content.trim()) return; setSaving(true); try { const result = await api.createJournal({ content, mood: mood.toLowerCase() || null, tags: [] }); setEntries((old) => [result, ...old]); toast("Your reflection was saved ✦"); setContent(""); setMood(""); setWriting(false); } catch { const localEntry = { _id: `local-${Date.now()}`, title: "A moment to remember", content, mood: mood.toLowerCase() || "reflective", created_at: new Date().toISOString() }; setEntries((old) => [localEntry, ...old]); toast("Saved privately on this device"); setContent(""); setMood(""); setWriting(false); } finally { setSaving(false); } };
  return <div className="shell py-10 sm:py-14"><PageHeader eyebrow="A private place for your thoughts" title="Your journal." description="There is no perfect way to write here. Just an honest one." action={<button onClick={() => setWriting(true)} className="btn-primary"><Plus size={17} /> New reflection</button>} />{writing && <form onSubmit={save} className="panel mb-6 p-6 sm:p-8"><div className="mb-5 flex items-center justify-between"><div><p className="eyebrow">Right now</p><h3 className="display mt-2 text-2xl font-semibold">What would you like to remember?</h3></div><button type="button" onClick={() => setWriting(false)} aria-label="Close editor"><X size={19} className="text-[#8ba095]" /></button></div><div className="mb-5 flex gap-2 overflow-auto pb-1 scrollbar-none">{moods.slice(0, 4).map((item) => <button type="button" key={item.label} onClick={() => setMood(item.label)} className={`rounded-full border px-3 py-2 text-xs font-semibold ${mood === item.label ? "border-moss bg-mint text-ink" : "border-[#dce7dc] text-[#7d9084]"}`}>{item.emoji} {item.label}</button>)}</div><textarea required autoFocus rows="7" className="input resize-none leading-7" placeholder={prompts[0]?.prompt || "Start with whatever is true for you today…"} value={content} onChange={(e) => setContent(e.target.value)} /><div className="mt-5 flex items-center justify-between"><span className="flex items-center gap-1.5 text-[11px] text-[#9aaa9f]"><LockKeyhole size={12} /> Only you can see this</span><button disabled={saving} className="btn-primary">{saving ? <Loader2 size={16} className="animate-spin" /> : "Save reflection"} {!saving && <ArrowRight size={15} />}</button></div></form>}<div className="grid gap-5 lg:grid-cols-[1.25fr_.75fr]"><section className="space-y-3">{entries.map((entry) => <article key={entry._id} className="panel group p-6 transition hover:border-sage"><div className="flex items-start justify-between gap-4"><div><span className="text-[11px] font-semibold uppercase tracking-wider text-[#99aaa0]">{new Date(entry.created_at || Date.now()).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}</span><h3 className="display mt-2 text-2xl font-semibold">{entry.title || "A moment to remember"}</h3></div><span className="rounded-full bg-[#eef5ee] px-3 py-1.5 text-xs font-semibold capitalize text-moss">{entry.mood || "reflective"}</span></div><p className="mt-4 text-sm leading-7 text-[#71847a]">{entry.content}</p><div className="mt-5 flex items-center justify-between border-t border-[#edf1ed] pt-4 text-[11px] text-[#9aaa9f]"><span>{entry.tags?.length ? entry.tags.map((tag) => `#${tag}`).join(" ") : "Personal reflection"}</span><button className="opacity-0 transition group-hover:opacity-100" onClick={async () => { try { await api.deleteJournal(entry._id); } catch {} setEntries((old) => old.filter((item) => item._id !== entry._id)); toast("Reflection removed"); }} title="Delete reflection"><Trash2 size={15} /></button></div></article>)}</section><aside className="space-y-5"><div className="rounded-[28px] bg-[#e7f0e7] p-7"><Wind size={22} className="text-moss" /><p className="eyebrow mt-7">A little prompt</p><h3 className="display mt-3 text-2xl font-semibold">You are allowed to take up space.</h3><p className="mt-3 text-sm leading-6 text-[#678173]">Your inner world deserves somewhere soft to land.</p><button onClick={() => { setWriting(true); setContent(prompts[Math.floor(Math.random() * Math.max(prompts.length, 1))]?.prompt || "What is asking for your attention today? "); }} className="mt-6 text-sm font-bold text-ink">Write from this <ArrowRight size={15} className="ml-1 inline" /></button></div><div className="panel p-6"><p className="eyebrow">Your patterns</p><div className="mt-5 flex items-end gap-2">{[28, 44, 35, 64, 48, 72, 57].map((height, index) => <div key={index} className="flex flex-1 flex-col items-center gap-2"><div style={{ height }} className={`w-full rounded-t-lg ${index === 5 ? "bg-moss" : "bg-[#d7e6d8]"}`} /><span className="text-[9px] text-[#9aaa9f]">{["M", "T", "W", "T", "F", "S", "S"][index]}</span></div>)}</div><p className="mt-4 text-xs text-[#819489]">You’ve made space for yourself {entries.length} times recently.</p></div></aside></div></div>;
}

function Books() {
  const [books, setBooks] = useState(fallbackBooks); const [query, setQuery] = useState(""); const [searching, setSearching] = useState(false); const [mood, setMood] = useState("Your current season");
  useEffect(() => { api.booksByMood().then((data) => { if (data.books?.length) { setBooks(data.books); setMood(data.mood || "Your current season"); } }).catch(() => {}); }, []);
  const search = async (event) => { event.preventDefault(); if (!query.trim()) return; setSearching(true); try { const data = await api.searchBooks(query); if (data.books?.length) setBooks(data.books); } catch { setBooks(fallbackBooks); } finally { setSearching(false); } };
  return <div className="shell py-10 sm:py-14"><PageHeader eyebrow="Reading for your wellbeing" title="The reading room." description="Books that meet you in the moment you’re in, and gently point toward where you want to go." /><div className="mb-8 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-2 text-sm text-[#7d9084]"><Sparkles size={16} className="text-coral" /> Curated for <span className="font-semibold capitalize text-ink">{mood}</span></div><form onSubmit={search} className="flex w-full max-w-xs items-center gap-2 rounded-full border border-[#d7e3d7] bg-white p-1.5 pl-4"><Search size={16} className="text-[#8ea097]" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search the shelves…" className="min-w-0 flex-1 bg-transparent text-xs outline-none" /><button className="rounded-full bg-ink px-3 py-2 text-[11px] font-semibold text-white">{searching ? <Loader2 size={13} className="animate-spin" /> : "Search"}</button></form></div><div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{books.map((book) => <article key={book.id} className="panel overflow-hidden p-3 transition hover:-translate-y-1 hover:shadow-soft"><div className="relative h-64 overflow-hidden rounded-[20px] bg-[#e5ebe5]"><img src={book.image_url || "https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=500&q=80"} alt="" className="h-full w-full object-cover transition duration-500 hover:scale-105" /><span className="absolute right-3 top-3 flex h-9 w-9 items-center justify-center rounded-full bg-white/85 text-moss"><BookmarkIcon /></span></div><div className="p-3"><p className="text-[11px] font-bold uppercase tracking-widest text-[#91a398]">{book.author || "A thoughtful read"}</p><h3 className="display mt-2 text-2xl font-semibold">{book.title}</h3><p className="mt-2 line-clamp-2 text-xs leading-5 text-[#7d9084]">{book.description || "A thoughtful companion for your wellbeing journey."}</p><button className="mt-5 flex items-center gap-2 text-xs font-bold text-moss">Explore book <ArrowRight size={14} /></button></div></article>)}</div></div>;
}
function BookmarkIcon() { return <BookOpen size={16} />; }

function Music() {
  const [songs, setSongs] = useState(["Bloom", "Weightless", "River Flows in You", "Holocene", "Sunset Lover"]); const [selected, setSelected] = useState("Bloom"); const [recommendations, setRecommendations] = useState([]); const [loading, setLoading] = useState(false);
  useEffect(() => { api.songs().then((data) => { if (data.songs?.length) setSongs(data.songs.slice(0, 20)); }).catch(() => {}); }, []);
  const getRecommendations = async () => { setLoading(true); try { const data = await api.recommendations(selected); setRecommendations(data.recommendations || []); } catch { setRecommendations([]); } finally { setLoading(false); } };
  const cards = recommendations.length ? recommendations : [{ name: "Bloom", artist: "The Paper Kites", album_cover_url: "https://images.unsplash.com/photo-1511379938547-c1f69419868d?w=600&q=80" }, { name: "Holocene", artist: "Bon Iver", album_cover_url: "https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=600&q=80" }, { name: "Anchor", artist: "Novo Amor", album_cover_url: "https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?w=600&q=80" }];
  return <div className="shell py-10 sm:py-14"><PageHeader eyebrow="Sound for your inner world" title="Your sound sanctuary." description="Sometimes a feeling needs a soundtrack before it needs a solution." /><section className="relative overflow-hidden rounded-[30px] bg-[#dcebdd] p-7 sm:p-10"><div className="relative z-10 max-w-md"><p className="eyebrow">Set the tone</p><h2 className="display mt-3 text-4xl font-semibold">What would feel good to hear?</h2><div className="mt-7 flex flex-col gap-3 sm:flex-row"><select className="input max-w-xs bg-white/80" value={selected} onChange={(e) => setSelected(e.target.value)}>{songs.map((song) => <option key={song}>{song}</option>)}</select><button onClick={getRecommendations} className="btn-primary bg-ink">{loading ? <Loader2 size={16} className="animate-spin" /> : <Music2 size={16} />} Find my sound</button></div></div><div className="absolute -right-10 -top-20 h-72 w-72 rounded-full border-[45px] border-white/25" /><div className="absolute -bottom-16 right-32 h-48 w-48 rounded-full border-[28px] border-[#b6d2ba]/60" /></section><div className="mt-8 flex items-end justify-between"><div><p className="eyebrow">A gentle playlist</p><h2 className="display mt-2 text-3xl font-semibold">For when you need a little room</h2></div><span className="hidden text-xs text-[#899c90] sm:block">{cards.length} tracks for your day</span></div><div className="mt-5 grid gap-4 md:grid-cols-3">{cards.map((song, index) => <article key={`${song.name}-${index}`} className="group panel flex items-center gap-4 p-4"><div className="relative h-20 w-20 shrink-0 overflow-hidden rounded-2xl bg-[#dbe7dc]"><img src={song.album_cover_url} alt="" className="h-full w-full object-cover" /><button className="absolute inset-0 m-auto flex h-9 w-9 scale-75 items-center justify-center rounded-full bg-white text-ink opacity-0 shadow-card transition group-hover:scale-100 group-hover:opacity-100"><Play size={15} fill="currentColor" /></button></div><div className="min-w-0"><p className="truncate font-semibold">{song.name}</p><p className="mt-1 truncate text-xs text-[#819489]">{song.artist}</p><div className="mt-3 flex items-center gap-1"><span className="h-1 w-1 rounded-full bg-moss" /><span className="text-[10px] uppercase tracking-wider text-[#9aaa9f]">{index === 0 ? "for grounding" : "recommended"}</span></div></div></article>)}</div></div>;
}

function Therapists() {
  const [therapists, setTherapists] = useState(fallbackTherapists); const [filter, setFilter] = useState(""); const [selected, setSelected] = useState(null); const [booking, setBooking] = useState(false); const [notice, setNotice] = useState("");
  useEffect(() => { api.therapists().then((data) => { if (data?.length) setTherapists(data); }).catch(() => {}); }, []);
  const filtered = therapists.filter((therapist) => !filter || therapist.specializations?.some((item) => item.toLowerCase().includes(filter.toLowerCase())));
  const book = async () => { if (!selected) return; setBooking(true); const start = new Date(Date.now() + 86400000 * 2); start.setHours(11, 0, 0, 0); const end = new Date(start); end.setHours(12); try { await api.bookAppointment({ user_id: "current-user", therapist_id: selected._id || selected.id, date: start.toISOString(), start_time: start.toISOString(), end_time: end.toISOString(), session_type: "video" }); setNotice("Your session request was sent."); } catch { setNotice("Connect your account to book a live session."); } finally { setBooking(false); } };
  return <div className="shell py-10 sm:py-14"><PageHeader eyebrow="Support that feels human" title="Find your person." description="The right therapist can make a world of difference. Browse people who bring warmth, skill, and room for your whole story." /><div className="mb-7 flex flex-wrap gap-2">{["", "Anxiety", "Relationships", "Life Transitions", "Self-Esteem"].map((item) => <button key={item || "all"} onClick={() => setFilter(item)} className={`rounded-full px-4 py-2.5 text-xs font-semibold transition ${filter === item ? "bg-ink text-white" : "border border-[#d9e4d9] bg-white text-[#70867a] hover:bg-mint"}`}>{item || "All therapists"}</button>)}</div><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{filtered.map((therapist) => <article key={therapist._id || therapist.id} className="panel overflow-hidden p-5"><div className="flex gap-4"><img src={therapist.photo_url} alt="" className="h-24 w-24 rounded-[22px] object-cover" /><div className="pt-1"><p className="text-lg font-semibold">{therapist.name}</p><p className="mt-1 text-xs text-[#829489]">{therapist.experience_years} years experience</p><div className="mt-3 flex items-center gap-1 text-xs font-semibold text-[#b48136]"><Star size={13} fill="currentColor" /> {therapist.rating} <span className="ml-1 font-normal text-[#98a99e]">({therapist.total_sessions}+ sessions)</span></div></div></div><p className="mt-5 line-clamp-2 text-sm leading-6 text-[#71857a]">{therapist.bio}</p><div className="mt-4 flex flex-wrap gap-1.5">{therapist.specializations?.slice(0, 3).map((tag) => <span key={tag} className="rounded-full bg-[#f0f5f0] px-2.5 py-1 text-[10px] font-semibold text-moss">{tag}</span>)}</div><div className="mt-5 flex items-center justify-between border-t border-[#e8eee8] pt-4"><p className="text-xs text-[#829489]"><span className="font-semibold text-ink">${therapist.hourly_rate}</span> / session</p><button onClick={() => { setSelected(therapist); setNotice(""); }} className="btn-primary px-4 py-2.5 text-xs">View profile <ArrowRight size={14} /></button></div></article>)}</div>{selected && <div className="fixed inset-0 z-50 flex items-center justify-center bg-ink/35 p-5 backdrop-blur-sm" onClick={() => setSelected(null)}><div className="panel max-h-[90vh] w-full max-w-lg overflow-auto p-7" onClick={(event) => event.stopPropagation()}><div className="flex items-start justify-between"><div className="flex gap-4"><img src={selected.photo_url} alt="" className="h-16 w-16 rounded-2xl object-cover" /><div><h2 className="display text-2xl font-semibold">{selected.name}</h2><p className="mt-1 text-xs text-[#829489]">{selected.education}</p></div></div><button onClick={() => setSelected(null)} aria-label="Close therapist profile"><X size={19} /></button></div><p className="mt-6 text-sm leading-7 text-[#71857a]">{selected.bio}</p><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-[#f3f7f3] p-4"><p className="text-[10px] uppercase tracking-wider text-[#94a59b]">Languages</p><p className="mt-2 text-sm font-semibold">{selected.languages?.join(", ")}</p></div><div className="rounded-2xl bg-[#f3f7f3] p-4"><p className="text-[10px] uppercase tracking-wider text-[#94a59b]">Session rate</p><p className="mt-2 text-sm font-semibold">${selected.hourly_rate} / hour</p></div></div><div className="mt-6 rounded-2xl border border-[#dce8dc] p-4"><p className="flex items-center gap-2 text-sm font-semibold"><CalendarDays size={16} className="text-moss" /> Next available</p><p className="mt-2 text-xs text-[#829489]">Monday, September 7 · 11:00 AM (your local time)</p></div>{notice && <p className="mt-4 rounded-xl bg-mint px-4 py-3 text-xs font-semibold text-moss">{notice}</p>}<button disabled={booking} onClick={book} className="btn-primary mt-6 w-full">{booking ? <Loader2 size={16} className="animate-spin" /> : <CalendarDays size={16} />} Request this session</button><p className="mt-3 text-center text-[10px] text-[#9aaa9f]">No commitment. You’ll confirm details before anything is scheduled.</p></div></div>}</div>;
}

function CoinsPage() {
  const [balance, setBalance] = useState(100); const [transactions, setTransactions] = useState([]); const [goals, setGoals] = useState([]); const [achievements, setAchievements] = useState([]);
  useEffect(() => { Promise.all([api.balance(), api.transactions(), api.dailyGoals(), api.achievements()]).then(([coin, tx, daily, badges]) => { setBalance(coin.balance || 100); setTransactions(tx || []); setGoals(daily || []); setAchievements(badges || []); }).catch(() => {}); }, []);
  return <div className="shell py-10 sm:py-14"><PageHeader eyebrow="A little encouragement goes a long way" title="Your calm coins." description="Earn coins for the care you put into yourself. Spend them on thoughtful extras when you’re ready." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><section className="relative overflow-hidden rounded-[30px] bg-ink p-8 text-white sm:p-10"><div className="absolute -right-8 -top-10 h-48 w-48 rounded-full border-[28px] border-white/10" /><p className="eyebrow text-sage">Current balance</p><div className="mt-4 flex items-end gap-3"><span className="display text-7xl font-semibold">{balance}</span><Coins size={28} className="mb-3 text-[#f4c88f]" /></div><p className="mt-3 text-sm text-[#a7bcb0]">Keep choosing small acts of care.</p><div className="mt-10 flex items-center gap-2 text-xs text-[#a7bcb0]"><Gift size={16} className="text-[#f4c88f]" /> You’re 100 coins away from a premium insight</div></section><section className="panel p-7"><div className="flex items-center justify-between"><div><p className="eyebrow">Today’s gentle goals</p><h3 className="display mt-2 text-2xl font-semibold">Care in small steps</h3></div><CircleDollarSign size={22} className="text-[#d89b43]" /></div><div className="mt-5 space-y-3">{(goals.length ? goals : [{ id: 1, title: "Chat with CalmBot", coins: 5, completed: false }, { id: 2, title: "Write in your journal", coins: 10, completed: true }, { id: 3, title: "Take a mindful pause", coins: 5, completed: false }]).slice(0, 3).map((goal) => <div key={goal.id} className="flex items-center gap-3 rounded-2xl bg-[#f5f8f5] p-3"><span className={`flex h-8 w-8 items-center justify-center rounded-xl ${goal.completed ? "bg-moss text-white" : "bg-white text-[#a1b0a6]"}`}>{goal.completed ? <Check size={15} /> : <Heart size={15} />}</span><span className="flex-1 text-sm font-semibold">{goal.title}</span><span className="text-xs font-bold text-[#ba8031]">+{goal.coins}</span></div>)}</div></section></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><section className="panel p-7"><div className="mb-5 flex items-center justify-between"><div><p className="eyebrow">Use your coins</p><h3 className="display mt-2 text-2xl font-semibold">Kind rewards</h3></div><ChevronRight size={18} className="text-[#8da095]" /></div>{[{ icon: Sparkles, name: "Premium insights", cost: 100, text: "See your wellbeing patterns" }, { icon: Wind, name: "Custom meditation", cost: 150, text: "A practice made for your moment" }, { icon: UserRound, name: "Therapist session", cost: 500, text: "One-on-one human support" }].map(({ icon: Icon, name, cost, text }) => <div key={name} className="flex items-center gap-3 border-b border-[#edf2ed] py-4 last:border-0"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#f6edde] text-[#bd8230]"><Icon size={17} /></span><div className="flex-1"><p className="text-sm font-semibold">{name}</p><p className="mt-0.5 text-[11px] text-[#8b9d92]">{text}</p></div><span className="text-xs font-bold text-[#a47735]">{cost} coins</span></div>)}</section><section className="panel p-7"><div className="mb-5 flex items-center justify-between"><div><p className="eyebrow">Recent activity</p><h3 className="display mt-2 text-2xl font-semibold">Your progress</h3></div><TrendingIcon /></div>{(transactions.length ? transactions : [{ description: "Welcome to ZenHeaven", amount: 100, timestamp: new Date().toISOString() }, { description: "Daily check-in", amount: 5, timestamp: new Date(Date.now() - 86400000).toISOString() }]).slice(0, 4).map((transaction, index) => <div key={`${transaction.description}-${index}`} className="flex items-center gap-3 border-b border-[#edf2ed] py-3 last:border-0"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#edf4ed] text-moss"><Plus size={14} /></span><p className="flex-1 text-xs font-semibold">{transaction.description}</p><span className="text-xs font-bold text-moss">+{transaction.amount}</span></div>)}</section></div><section className="mt-5 panel p-7"><p className="eyebrow">Milestones</p><div className="mt-5 grid gap-3 sm:grid-cols-3">{(achievements.length ? achievements : [{ title: "First steps", description: "Started your journey", unlocked: true, coins: 50 }, { title: "Consistent chatter", description: "Chat for 7 days", unlocked: false, coins: 100 }, { title: "Wellness warrior", description: "Earn 1,000 coins", unlocked: false, coins: 300 }]).map((item) => <div key={item.title} className={`rounded-2xl border p-4 ${item.unlocked ? "border-[#cadfca] bg-[#f2f8f2]" : "border-[#e5ebe5]"}`}><div className="flex items-center justify-between"><Star size={18} className={item.unlocked ? "text-[#d99b3e]" : "text-[#b4c0b7"} fill={item.unlocked ? "currentColor" : "none"} /><span className="text-[10px] font-semibold text-[#a67a39]">+{item.coins}</span></div><p className="mt-4 text-sm font-semibold">{item.title}</p><p className="mt-1 text-[11px] text-[#8a9c91]">{item.description}</p></div>)}</div></section></div>;
}
function TrendingIcon() { return <span className="text-lg text-moss">↗</span>; }

function Protected({ user, children }) { return user ? children : <Navigate to="/login" replace />; }

export default function App() {
  const [user, setUser] = useState(null); const [toast, setToast] = useState("");
  useEffect(() => { if (localStorage.getItem("zenheaven_token")) api.me().then(setUser).catch(() => { localStorage.removeItem("zenheaven_token"); }); }, []);
  const logout = () => { localStorage.removeItem("zenheaven_token"); setUser(null); };
  const notify = (message) => { setToast(message); window.setTimeout(() => setToast(""), 3000); };
  return <><Routes><Route path="/" element={user ? <Navigate to="/dashboard" replace /> : <Landing />} /><Route path="/login" element={user ? <Navigate to="/dashboard" replace /> : <AuthPage mode="login" onAuth={setUser} />} /><Route path="/register" element={user ? <Navigate to="/dashboard" replace /> : <AuthPage mode="register" onAuth={setUser} />} /><Route path="*" element={<Protected user={user}><AppShell user={user} onLogout={logout}><Routes><Route path="/dashboard" element={<Dashboard user={user} toast={notify} />} /><Route path="/chat" element={<Chat />} /><Route path="/journal" element={<Journal toast={notify} />} /><Route path="/books" element={<Books />} /><Route path="/music" element={<Music />} /><Route path="/therapists" element={<Therapists />} /><Route path="/coins" element={<CoinsPage />} /><Route path="*" element={<Navigate to="/dashboard" replace />} /></Routes></AppShell></Protected>} /></Routes><Toast message={toast} onClose={() => setToast("")} /></>;
}
